1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = {
41	  premium: number;
42	};
43	
44	export type ClaimResult = {
45	  payout: number;
46	  remainingCap: number;
47	};
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioResult = {
52	  results: StepResult[];
53	};
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const INSURANCE_VALUES: Record<string, number> = {
68	  sword: 1000,
69	  amulet: 600,
70	  staff: 800,
71	  potion: 400,
72	  rune: 250,
73	  moonstone: 250,
74	};
75	
76	const DEDUCTIBLE_PER_DAMAGE = 100;
77	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
78	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
79	const FULL_REIMBURSEMENT_RATE = 1;
80	const CAP_MULTIPLIER = 2;
81	
82	const CURSE_SURCHARGE_RATE = 0.5;
83	const HIGH_ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
84	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
85	const LOYALTY_YEARS_THRESHOLD = 2;
86	const LOYALTY_DISCOUNT_RATE = 0.2;
87	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
88	
89	const BLOCK_SIZE = 3;
90	const BLOCK_BASE_PREMIUM = 60;
91	
92	const basePremiumForType = (type: string): number => BASE_PREMIUMS[type];
93	
94	const itemBasePremium = (item: Item): number => basePremiumForType(item.type);
95	
96	const countByType = (items: Item[]): Map<string, number> => {
97	  const counts = new Map<string, number>();
98	  for (const item of items) {
99	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
100	  }
101	  return counts;
102	};
103	
104	// A block is exactly BLOCK_SIZE alike items, charged as one unit.
105	const formsBlock = (count: number): boolean => count === BLOCK_SIZE;
106	
107	const groupBasePremium = (type: string, count: number): number =>
108	  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * basePremiumForType(type);
109	
110	const policyBasePremium = (items: Item[]): number =>
111	  [...countByType(items)].reduce(
112	    (total, [type, count]) => total + groupBasePremium(type, count),
113	    0,
114	  );
115	
116	// The MHPCO rounds in its own favour: premiums up, payouts down.
117	const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
118	
119	// Item-scoped surcharge clauses. Each applies, independently and additively,
120	// to the affected item's own base premium.
121	const ITEM_SURCHARGE_CLAUSES: {
122	  applies: (item: Item) => boolean;
123	  rate: number;
124	}[] = [
125	  {
126	    applies: (item) => item.cursed === true,
127	    rate: CURSE_SURCHARGE_RATE,
128	  },
129	  {
130	    applies: (item) =>
131	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_SURCHARGE_THRESHOLD,
132	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
133	  },
134	];
135	
136	const itemSurcharge = (item: Item): number => {
137	  const base = itemBasePremium(item);
138	
139	  return ITEM_SURCHARGE_CLAUSES.filter((clause) => clause.applies(item)).reduce(
140	    (total, clause) => total + base * clause.rate,
141	    0,
142	  );
143	};
144	
145	const itemSurcharges = (items: Item[]): number =>
146	  items.reduce((total, item) => total + itemSurcharge(item), 0);
147	
148	// Everything a policy-scoped clause may inspect.
149	type Policy = {
150	  items: Item[];
151	  customer: Customer;
152	  isFollowUpContract: boolean;
153	};
154	
155	// Policy-scoped modifier clauses. Each applies, independently and additively,
156	// to the policy base premium. A negative rate is a discount.
157	const POLICY_MODIFIER_CLAUSES: {
158	  applies: (policy: Policy) => boolean;
159	  rate: number;
160	}[] = [
161	  {
162	    applies: () => true,
163	    rate: FIRST_INSURANCE_SURCHARGE_RATE,
164	  },
165	  {
166	    applies: (policy) =>
167	      policy.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
168	    rate: -LOYALTY_DISCOUNT_RATE,
169	  },
170	  {
171	    applies: (policy) => policy.isFollowUpContract,
172	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
173	  },
174	];
175	
176	const policyModifiers = (policy: Policy, policyBase: number): number =>
177	  POLICY_MODIFIER_CLAUSES.filter((clause) => clause.applies(policy)).reduce(
178	    (total, clause) => total + policyBase * clause.rate,
179	    0,
180	  );
181	
182	const quote = (policy: Policy): QuoteResult => {
183	  const policyBase = policyBasePremium(policy.items);
184	  const modifiedPremium =
185	    policyBase + itemSurcharges(policy.items) + policyModifiers(policy, policyBase);
186	
187	  return {
188	    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
189	  };
190	};
191	
192	const insuranceSum = (items: Item[]): number =>
193	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
194	
195	// A policy issued by a quote step, tracked so later claims can draw on its cap.
196	type IssuedPolicy = {
197	  items: Item[];
198	  remainingCap: number;
199	};
200	
201	// The cap a fresh policy starts with: a multiple of the insured items' value,
202	// independent of any premium modifiers.
203	const issuePolicy = (items: Item[]): IssuedPolicy => ({
204	  items,
205	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
206	});
207	
208	// Item-scoped reimbursement clauses. Unlike the additive premium surcharges,
209	// these compete: the first applicable clause sets the rate outright, so list
210	// order is precedence. An item no clause applies to is reimbursed in full.
211	//
212	// The spec's dragon-material clause ("fully reimbursed") is deliberately not
213	// listed. Full reimbursement is already the default, and where it would
214	// collide with the high-enchantment clause the spec says the 50 % rule wins —
215	// which is what precedence gives. A dragon row would therefore be
216	// unreachable: no input distinguishes its presence from its absence.
217	const ITEM_REIMBURSEMENT_CLAUSES: {
218	  applies: (item: Item) => boolean;
219	  rate: number;
220	}[] = [
221	  {
222	    applies: (item) =>
223	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD,
224	    rate: HIGH_ENCHANTMENT_REIMBURSEMENT_RATE,
225	  },
226	];
227	
228	const reimbursementRate = (item: Item): number =>
229	  ITEM_REIMBURSEMENT_CLAUSES.find((clause) => clause.applies(item))?.rate ??
230	  FULL_REIMBURSEMENT_RATE;
231	
232	// Reimbursement clauses read the damaged item, so a claim resolves each
233	// damage entry back to the insured item it refers to.
234	const reimbursedAmount = (item: Item, amount: number): number =>
235	  amount * reimbursementRate(item);
236	
237	const insuredItemFor = (damage: Damage, items: Item[]): Item =>
238	  items.find((item) => item.type === damage.itemType)!;
239	
240	// Each damaged item carries its own deductible, and a damage smaller than the
241	// deductible contributes nothing rather than clawing money back off the claim.
242	const payoutForDamage = (damage: Damage, items: Item[]): number => {
243	  const item = insuredItemFor(damage, items);
244	  const reimbursed = reimbursedAmount(item, damage.amount);
245	
246	  return Math.max(0, reimbursed - DEDUCTIBLE_PER_DAMAGE);
247	};
248	
249	const payoutForIncident = (incident: Incident, items: Item[]): number =>
250	  incident.damages.reduce(
251	    (total, damage) => total + payoutForDamage(damage, items),
252	    0,
253	  );
254	
255	// A claim draws its payout down from the policy's remaining cap, so the
256	// policy carries less cover into any later claim against it.
257	const drawDownCap = (policy: IssuedPolicy, payout: number): IssuedPolicy => ({
258	  ...policy,
259	  remainingCap: policy.remainingCap - payout,
260	});
261	
262	export const runScenario = (scenario: Scenario): ScenarioResult => {
263	  let hasIssuedContract = false;
264	  const policies = new Map<number, IssuedPolicy>();
265	
266	  const results = scenario.steps.map((step, index): StepResult => {
267	    if (step.op === "claim") {
268	      const issued = policies.get(step.policy)!;
269	      const payout = Math.min(
270	        payoutForIncident(step.incident, issued.items),
271	        issued.remainingCap,
272	      );
273	      const policy = drawDownCap(issued, payout);
274	      policies.set(step.policy, policy);
275	
276	      return { payout, remainingCap: policy.remainingCap };
277	    }
278	
279	    policies.set(index, issuePolicy(step.items));
280	
281	    const result = quote({
282	      items: step.items,
283	      customer: scenario.customer,
284	      isFollowUpContract: hasIssuedContract,
285	    });
286	    hasIssuedContract = true;
287	
288	    return result;
289	  });
290	
291	  return { results };
292	};
